From 2178f57dbce4b006c36db7dd7cf6c255d346e3fe Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 23:30:09 +0100
Subject: [PATCH] libkworkspace: restart into a loaded kexec kernel like
 systemctl reboot

Restarting from Plasma always did a full firmware reboot, even when a
kexec kernel had been loaded to skip it. Ask logind to reboot with the
kexec flag, falling back to the plain call on logind older than v254.

BUG: 458809
---
 libkworkspace/sessionmanagementbackend.cpp | 15 ++++++++++++++-
 1 file changed, 14 insertions(+), 1 deletion(-)

diff --git a/libkworkspace/sessionmanagementbackend.cpp b/libkworkspace/sessionmanagementbackend.cpp
index d0742bfb9a..ed76b56a23 100644
--- a/libkworkspace/sessionmanagementbackend.cpp
+++ b/libkworkspace/sessionmanagementbackend.cpp
@@ -12,6 +12,7 @@

 #include <QDBusConnection>
 #include <QDBusConnectionInterface>
+#include <QDBusMessage>
 #include <QDBusPendingCallWatcher>

 #include <KConfigGroup>
@@ -182,7 +183,19 @@ void LogindSessionBackend::shutdown()

 void LogindSessionBackend::reboot()
 {
-    m_login1->Reboot(true).waitForFinished();
+    // Like systemctl reboot, boot straight into a kexec kernel if one has been loaded
+    constexpr quint64 SD_LOGIND_KEXEC_REBOOT = 1 << 1;
+    QDBusMessage message = QDBusMessage::createMethodCall(m_login1->service(), m_login1->path(), m_login1->interface(), QStringLiteral("RebootWithFlags"));
+    message << SD_LOGIND_KEXEC_REBOOT;
+    message.setInteractiveAuthorizationAllowed(true);
+    const QDBusMessage reply = m_login1->connection().call(message);
+
+    // logind older than v254 doesn't know about the flag
+    if (reply.type() == QDBusMessage::ErrorMessage
+        && (reply.errorName() == QLatin1String("org.freedesktop.DBus.Error.UnknownMethod")
+            || reply.errorName() == QLatin1String("org.freedesktop.DBus.Error.InvalidArgs"))) {
+        m_login1->Reboot(true).waitForFinished();
+    }
 }

 void LogindSessionBackend::suspend()
